#include <iostream>
using namespace std;

int linearSearch(int arr[], int n, int key) {
    for (int i = 0; i < n; i++) {
        if (arr[i] == key)
            return i;              // found
    }
    return -1;                     // not found
}

int main() {
    int a[] = {14, 7, 23, 9, 31, 18};
    int n = sizeof(a) / sizeof(a[0]);
    int key;
    cout << "Enter number to search: ";
    cin >> key;
    int pos = linearSearch(a, n, key);
    if (pos != -1)
        cout << key << " found at index " << pos << " (position " << pos + 1
<< ")" << endl;
    else
        cout << key << " not found" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int binarySearch(int arr[], int n, int key) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == key)      return mid;
        else if (key < arr[mid])  high = mid - 1;
        else                      low = mid + 1;
    }
    return -1;
}

int main() {
    int a[] = {10, 20, 30, 40, 50, 60, 70, 80, 90};
    int n = 9;
    cout << binarySearch(a, n, 70) << endl;   // 6
    cout << binarySearch(a, n, 25) << endl;   // -1
    return 0;
}

int binarySearchRec(int arr[], int low, int high, int key) {
    if (low > high) return -1;                         // base case: empty range
    int mid = low + (high - low) / 2;
    if (arr[mid] == key) return mid;
    if (key < arr[mid])
        return binarySearchRec(arr, low, mid - 1, key);    // left half
    else
        return binarySearchRec(arr, mid + 1, high, key);   // right half
}
