string lower(string s) {
    for (char &c : s) c = tolower(c);
    return s;
}

int main() {
    string names[] = {"Aarav", "Diya", "Kabir", "Meera", "Zoya"};
    string target;
    cout << "Name to search: ";
    cin >> target;
    for (int i = 0; i < 5; i++) {
        if (lower(names[i]) == lower(target)) {
            cout << "Found " << names[i] << " at position " << i + 1 << endl;
            return 0;
        }
    }
    cout << target << " is not in the list" << endl;
    return 0;
}

struct Student { int roll; string name; int marks; };

int findByRoll(Student s[], int n, int roll) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (s[mid].roll == roll) return mid;
        if (roll < s[mid].roll) high = mid - 1;
        else                    low = mid + 1;
    }
    return -1;
}

int main() {
    Student cls[] = {{101, "Aman", 78}, {104, "Priya", 92}, {107, "Rahul",
85},
                     {110, "Sana", 88}, {115, "Vikas", 69}};
    int idx = findByRoll(cls, 5, 110);
    if (idx != -1)
        cout << cls[idx].name << " scored " << cls[idx].marks << endl;   // Sana scored 88
    else
        cout << "Roll number not found" << endl;
}

#include <iostream>
using namespace std;

int main() {
    const int N = 100;
    int a[N];
    for (int i = 0; i < N; i++) a[i] = i + 1;      // 1, 2, ..., 100 (sorted)
    int key = 73;

    int linComp = 0;
    for (int i = 0; i < N; i++) { linComp++; if (a[i] == key) break; }

    int binComp = 0, low = 0, high = N - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        binComp++;
        if (a[mid] == key) break;
        if (key < a[mid]) high = mid - 1; else low = mid + 1;
    }
    cout << "Linear: " << linComp << " comparisons" << endl;
    cout << "Binary: " << binComp << " comparisons" << endl;
    return 0;
}

