    while (ss >> w) freq[w]++;          // look up the word and add 1, in about one step

    cout << "the: " << freq["the"] << endl;    // 3
    cout << "and: " << freq["and"] << endl;    // 2
    cout << "cat: " << freq["cat"] << endl;    // 1
