}

vector<int> v = {2, 4, 4, 4, 7, 9};
auto first = lower_bound(v.begin(), v.end(), 4);   // first item >= 4
auto last  = upper_bound(v.begin(), v.end(), 4);   // first item  > 4
if (first != v.end() && *first == 4) {
    cout << "First index: " << first - v.begin() << endl;      // 1
    cout << "Last index: "  << (last - v.begin()) - 1 << endl; // 3
    cout << "Count: "       << last - first << endl;           // 3
}
